import{_ as a,o as s,c as i,ag as d}from"./chunks/framework.DoUXNnsN.js";const u=JSON.parse('{"title":"Modbus-TCP","description":"","frontmatter":{"title":"Modbus-TCP","aliases":["Modbus TCP","Modbus/TCP","MBAP","MBAP报文头","端口502"],"tags":["工业通信","Modbus"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/Modbus","https://www.modbus.org/file/secure/messagingimplementationguide.pdf","https://www.simplymodbus.ca/FC03.htm","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":5},"headers":[],"relativePath":"70-工业通信与自动化/Modbus/Modbus-TCP.md","filePath":"70-工业通信与自动化/Modbus/Modbus-TCP.md"}'),e={name:"70-工业通信与自动化/Modbus/Modbus-TCP.md"};function o(l,t,r,n,h,p){return s(),i("div",null,[...t[0]||(t[0]=[d(`<blockquote><p>本篇是 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a> 入门路径的第 5 篇（最后一篇）。读完你应该能：说出 Modbus TCP 报文每个字节的含义；把一条 RTU 请求改写成 TCP 请求；理解事务号和单元号的作用；排查以太网上的 Modbus 通信问题。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>Modbus TCP 是 Modbus 跑在**以太网（TCP/IP）**上的形式：把功能码和数据（PDU）前面加一个 7 字节的 <strong>MBAP 报文头</strong>，通过 TCP 连接发送，默认使用端口 <strong>502</strong>。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus功能码">Modbus功能码</a>：知道 PDU 是什么。</li><li><a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a>：知道 IP 地址、端口、TCP 连接是什么。简单说：TCP 在两台电脑之间建立一条可靠的&quot;数据管道&quot;，数据按顺序、不丢失地送到。</li><li><a href="/Encyclopedia/10-计算机基础/数据表示/十六进制">十六进制</a>。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>串口的速度慢、距离和设备数有限、布线麻烦。工厂已经铺好了以太网，把 Modbus 搬到以太网上，就能：</p><ul><li>用更快的速度，一台电脑同时和很多台设备通信；</li><li>利用已有的网线、交换机，不用再拉 RS-485 总线；</li><li>通过网关把老式串口设备接入以太网（后面讲）。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="和-rtu-的三个区别" tabindex="-1">和 RTU 的三个区别 <a class="header-anchor" href="#和-rtu-的三个区别" aria-label="Permalink to &quot;和 RTU 的三个区别&quot;">​</a></h3><ol><li><strong>没有 CRC</strong>。TCP 本身已经能保证数据不出错、不丢失，Modbus TCP 不再重复校验。</li><li><strong>没有从站地址字节</strong>，改成 MBAP 头里的&quot;单元标识&quot;。</li><li><strong>不靠静默间隔分帧</strong>。TCP 是一条字节流，靠 MBAP 头里的&quot;长度&quot;字段知道一帧有多长。</li></ol><h3 id="mbap-报文头-7-个字节" tabindex="-1">MBAP 报文头：7 个字节 <a class="header-anchor" href="#mbap-报文头-7-个字节" aria-label="Permalink to &quot;MBAP 报文头：7 个字节&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>含义</th></tr></thead><tbody><tr><td>事务标识</td><td>2 字节</td><td>主站给每次请求编的号，从站回应时原样带回，用来把回应和请求对上</td></tr><tr><td>协议标识</td><td>2 字节</td><td>Modbus 恒为 0</td></tr><tr><td>长度</td><td>2 字节</td><td><strong>后面还有多少字节</strong>（单元标识 + PDU）</td></tr><tr><td>单元标识</td><td>1 字节</td><td>目标设备的地址；不需要时设为 255（维基百科转述规范），有的设备要求填 1 或 0，以设备手册为准</td></tr></tbody></table><p>后面紧跟 PDU（功能码 + 数据）。整帧最长 7 + 253 = 260 字节。</p><h3 id="一个完整例子-逐字节拆解" tabindex="-1">一个完整例子，逐字节拆解 <a class="header-anchor" href="#一个完整例子-逐字节拆解" aria-label="Permalink to &quot;一个完整例子，逐字节拆解&quot;">​</a></h3><p>和 RTU 篇里一样：读 17 号单元（十六进制 0x11）的 3 个保持寄存器，起始地址 107（0x6B）。</p><p><strong>RTU 形式</strong>（对照用）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>11 03 00 6B 00 03 76 87</span></span></code></pre></div><p><strong>TCP 形式</strong>（事务号设为 1）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>00 01  00 00  00 06  11  03 00 6B 00 03</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字节</th><th>含义</th></tr></thead><tbody><tr><td><code>00 01</code></td><td>事务标识 = 1</td></tr><tr><td><code>00 00</code></td><td>协议标识 = 0（Modbus）</td></tr><tr><td><code>00 06</code></td><td>长度 = 6：后面有 6 个字节</td></tr><tr><td><code>11</code></td><td>单元标识 = 17</td></tr><tr><td><code>03</code></td><td>功能码：读保持寄存器</td></tr><tr><td><code>00 6B</code></td><td>起始地址 107</td></tr><tr><td><code>00 03</code></td><td>数量 3</td></tr></tbody></table><p><strong>长度怎么算</strong>：单元标识 1 + 功能码 1 + 起始地址 2 + 数量 2 = 6。</p><p>两种形式对比：RTU 把地址放在最前面、CRC 放在最后；TCP 用 MBAP 头取代了它们。<strong>中间的 <code>03 00 6B 00 03</code> 完全一样</strong>，所以前面学的功能码、数据模型对两种形式通用。</p><p><strong>回应</strong>（TCP，假设从站返回的值和 RTU 篇一致）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>00 01  00 00  00 09  11  03 06 AE41 5652 4340</span></span></code></pre></div><p>事务标识 <code>00 01</code> 原样带回；长度 <code>00 09</code> = 单元标识 1 + 功能码 1 + 字节数 1 + 数据 6 = 9。</p><h3 id="事务标识有什么用" tabindex="-1">事务标识有什么用 <a class="header-anchor" href="#事务标识有什么用" aria-label="Permalink to &quot;事务标识有什么用&quot;">​</a></h3><p>TCP 允许主站<strong>连续发多个请求</strong>而不必等上一个回应（所谓&quot;流水线&quot;），从站按处理完成的顺序回应，回应的顺序不一定和请求的顺序一样。主站靠事务标识知道&quot;这个回应是哪个请求的&quot;。简单应用里每次发一个等一个，事务标识就从 1 开始递增即可（实验里就是这样做的）。</p><h3 id="单元标识和网关" tabindex="-1">单元标识和网关 <a class="header-anchor" href="#单元标识和网关" aria-label="Permalink to &quot;单元标识和网关&quot;">​</a></h3><p>如果主站要访问的是接在<strong>网关</strong>后面的串口设备（RS-485 的老设备），网关一边是以太网（Modbus TCP），一边是串口（Modbus RTU）。主站通过 TCP 发请求，把<strong>串口设备的从站地址</strong>填进单元标识；网关收到后，去掉 MBAP 头，加上 CRC，转成 RTU 帧发到串口上，再把回应转回 TCP 帧。这样一个网关就能让一台电脑用以太网访问挂在 RS-485 总线上的几十台设备。</p><h3 id="连接方式" tabindex="-1">连接方式 <a class="header-anchor" href="#连接方式" aria-label="Permalink to &quot;连接方式&quot;">​</a></h3><ul><li>从站（服务器）在 502 端口监听，主站（客户端）主动发起 TCP 连接；</li><li>一条连接上可以长期收发，<strong>不要每次读写都重新建立连接</strong>，否则既慢又容易耗尽端口；</li><li>设备通常限制同时连接数（几个到几十个），多个上位机同时连一个设备时要注意；</li><li>连接断开后（网线松动、设备重启），主站要能检测并重连。</li></ul><h3 id="安全-modbus-没有任何保护" tabindex="-1">安全：Modbus 没有任何保护 <a class="header-anchor" href="#安全-modbus-没有任何保护" aria-label="Permalink to &quot;安全：Modbus 没有任何保护&quot;">​</a></h3><p>原始的 Modbus TCP <strong>没有认证、也没有加密</strong>：任何能连上 502 端口的人都能读写设备的数据，包括让设备停机。所以：</p><ul><li>设备网络要和办公网络、互联网<strong>隔离</strong>；</li><li>不要把 502 端口暴露到外网；</li><li>需要远程访问时，使用 VPN、防火墙白名单等手段。</li></ul><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p><a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a> 总览里的动手实验就是 Modbus TCP：客户端发的每一行就是一个 MBAP + PDU。建议你再做三个小改动，加深理解：</p><ol><li><strong>观察事务号</strong>：在 <code>modbus_client.py</code> 的 <code>request</code> 函数里，把 <code>_tid</code> 改名为 <code>rsp_tid</code> 并多打印一行 <code>print(&quot;回应事务号:&quot;, rsp_tid)</code>，再把 <code>main</code> 里某次调用的事务号改成 <code>0x1234</code>（十进制 4660）。运行后你会看到回应带回的事务号和你发的一样。</li><li><strong>换单元号</strong>：把 <code>UNIT</code> 改成 <code>17</code>。模拟从站没有检查单元号，所以仍然正常回应。思考：真实设备如果只认某个单元号，会发生什么？（常见表现是没有回应，具体看设备手册。）</li><li><strong>用 Python 拼一个请求</strong>：下面这行代码构造本篇的例子，结果应该是 <code>00 01 00 00 00 06 11 03 00 6b 00 03</code>：</li></ol><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> struct</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(struct.pack(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&gt;HHHBBHH&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6B</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).hex(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot; &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>（这行代码我已实际运行验证。<code>&gt;HHHBBHH</code> 的意思：大端，三个 2 字节整数、两个 1 字节整数、再两个 2 字节整数，依次对应事务号、协议号、长度、单元号、功能码、起始地址、数量。）</p><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>最可能的原因</th></tr></thead><tbody><tr><td>连不上，一直超时</td><td>IP 不对；不在同一网段；防火墙拦截；设备的 Modbus 服务没开；端口不是 502</td></tr><tr><td>连接上了但没有回应</td><td>单元标识不对；功能码不支持；设备同时连接数已满</td></tr><tr><td>偶尔读不到，重连后又好</td><td>网线松动、交换机问题、设备限制了空闲连接时间被主动断开</td></tr><tr><td>回应的事务号对不上</td><td>主站没有按事务号配对，把&quot;上一次的迟到回应&quot;当成了这次的</td></tr><tr><td>读到的值整体延迟</td><td>轮询周期太长，或者缓存了旧数据</td></tr><tr><td>通过网关访问串口设备不稳定</td><td>网关的串口参数（波特率等）和设备不一致；网关把多个主站的请求排队；串口那边超时设置过短</td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>写出读取 1 号单元、从地址 0 开始的 2 个保持寄存器的 Modbus TCP 请求，事务号 7。 <strong>答</strong>：<code>00 07 00 00 00 06 01 03 00 00 00 02</code>（长度 6 = 1 + 1 + 2 + 2）。</li><li>收到 <code>00 05 00 00 00 05 01 03 02 00 FA</code>，是什么意思？ <strong>答</strong>：事务号 5；协议号 0；长度 5；单元 1；功能码 03；数据 2 字节：<code>0x00FA</code> = 250。若手册说温度单位是 0.1 ℃，那就是 25.0 ℃。</li><li>为什么 Modbus TCP 不需要 CRC？ <strong>答</strong>：因为下层的 TCP/IP 已经提供了数据校验和重传，传输出错的数据不会交给应用层。</li><li>一台只有一个以太网口的网关后面挂着 3 台串口设备，地址分别是 1、2、3。主站读 2 号设备时，请求的哪个字段要填 2？ <strong>答</strong>：MBAP 头里的单元标识。网关用它决定把请求转发给串口上的哪台设备。</li><li>你发了一个读请求，回应的 MBAP 头里长度是 <code>00 05</code>，但只收到 4 个字节的后续数据，应该怎么办？ <strong>答</strong>：TCP 是字节流，可能还没收全，要继续接收直到收满长度字段指定的字节数（这正是实验脚本里 <code>recv_exact</code> 做的事），而不是只调用一次接收。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Modbus TCP = MBAP 头（7 字节）+ PDU，端口 502，无 CRC。</li><li>MBAP 头：事务标识、协议标识（0）、长度、单元标识。长度 = 单元标识 + PDU 的字节数。</li><li>事务标识用来配对请求与回应；单元标识在网关场景下指定串口设备的地址。</li><li>保持长连接，注意设备的连接数限制；一帧要收满长度字段指定的字节。</li><li>没有认证和加密，必须靠网络隔离来保护。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus功能码">Modbus功能码</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus数据模型与地址">Modbus数据模型与地址</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus-RTU">Modbus-RTU</a>、<a href="/Encyclopedia/10-计算机基础/计算机网络/TCP-IP">TCP-IP</a>、<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a>、<a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Modbus 官方 TCP/IP 实现指南：<a href="https://www.modbus.org/file/secure/messagingimplementationguide.pdf" target="_blank" rel="noreferrer">https://www.modbus.org/file/secure/messagingimplementationguide.pdf</a></li><li>维基百科 Modbus 词条（含 MBAP 头的描述）：<a href="https://en.wikipedia.org/wiki/Modbus" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Modbus</a></li></ul>`,50)])])}const b=a(e,[["render",o]]);export{u as __pageData,b as default};
